(6761792, 1011855, 127021, '<td valign="top">excellent use of dof and the composition is spot on</td>', 'excellent use of dof and the composition is spot on', '2012-05-07 06:44:46.000000', NULL, 1),
(6761793, 1012167, 127021, '<td valign="top">very creative photo and the processing really brings out the contrast - nice work.</td>', 'very creative photo and the processing really brings out the contrast - nice work.', '2012-05-07 06:45:09.000000', NULL, 1),
(6762054, 1013173, 114225, '<td valign="top">What a great example for this challenge. I''m seeing the image as not super crisp, which brings my vote down a bit.</td>', 'What a great example for this challenge. I''m seeing the image as not super crisp, which brings my vote down a bit.', '2012-05-07 13:09:32.000000', NULL, 1),
(6762057, 1012527, 114225, '<td valign="top">Well seen image. Good use of minimalism.</td>', 'Well seen image. Good use of minimalism.', '2012-05-07 13:10:54.000000', NULL, 1),
(6762058, 1013032, 114225, '<td valign="top">What a cool idea, and well executed.</td>', 'What a cool idea, and well executed.', '2012-05-07 13:11:12.000000', NULL, 1),
(6762060, 1012896, 114225, '<td valign="top">I''m surprised to see no curls of lemon skin on the ground. I think a little detail like that could have brought this to the next leave.</td>', 'I''m surprised to see no curls of lemon skin on the ground. I think a little detail like that could have brought this to the next leave.', '2012-05-07 13:12:14.000000', NULL, 1),
(6762069, 1012453, 114225, '<td valign="top">Very well seen image. It''s great how there is even a curved road.</td>', 'Very well seen image. It''s great how there is even a curved road.', '2012-05-07 13:15:39.000000', NULL, 1),
(6762073, 1012003, 114225, '<td valign="top">I''m liking the color choice here.</td>', 'I''m liking the color choice here.', '2012-05-07 13:16:17.000000', NULL, 1),
(6762080, 1013177, 114225, '<td valign="top">Interesting choice of light. I''m wondering why youwent with the white paper like surface. Maybe a dark wood could have helped the noodles pop out more.</td>', 'Interesting choice of light. I''m wondering why youwent with the white paper like surface. Maybe a dark wood could have helped the noodles pop out more.', '2012-05-07 13:17:27.000000', NULL, 1),
(6762092, 1013259, 114225, '<td valign="top">With more sharpness I think this could have been an interesting study.</td>', 'With more sharpness I think this could have been an interesting study.', '2012-05-07 13:29:59.000000', NULL, 1),
(6762093, 1013156, 114225, '<td valign="top">Well done. I like the little hilits of color.</td>', 'Well done. I like the little hilits of color.', '2012-05-07 13:30:15.000000', NULL, 1),
(6762122, 1013096, 114225, '<td valign="top">Very pleasing light for this shot. I really like the way you composed it.</td>', 'Very pleasing light for this shot. I really like the way you composed it.', '2012-05-07 14:14:01.000000', NULL, 1),
(6762267, 1013095, 66384, '<td valign="top">Beautiful high key shot.</td>', 'Beautiful high key shot.', '2012-05-07 17:18:45.000000', NULL, 1),
(6762271, 1013177, 66384, '<td valign="top">This feels all backward. The eye naturally goes to the light, but the focus on this shot is in the darker area. It doesn''t work for me.</td>', 'This feels all backward. The eye naturally goes to the light, but the focus on this shot is in the darker area. It doesn''t work for me.', '2012-05-07 17:21:03.000000', NULL, 1),
(6762272, 1012642, 66384, '<td valign="top">Nice lines and DOF.</td>', 'Nice lines and DOF.', '2012-05-07 17:21:49.000000', NULL, 1),
(6762273, 1012180, 66384, '<td valign="top">Yep, too many. I''m sure many voters will like this, because the colors are lovely, and the subject is interesting, but it feels too busy to me.</td>', 'Yep, too many. I''m sure many voters will like this, because the colors are lovely, and the subject is interesting, but it feels too busy to me.', '2012-05-07 17:24:18.000000', NULL, 1),
(6762275, 1013032, 66384, '<td valign="top">Very nice light composition and simplicity. And definitely twisted. Goog entry.</td>', 'Very nice light composition and simplicity. And definitely twisted. Goog entry.', '2012-05-07 17:26:45.000000', NULL, 1),
(6762279, 1013117, 66384, '<td valign="top">I think it would have been better without the extra piece of mettle breaking up the nice curves of the spring.</td>', 'I think it would have been better without the extra piece of mettle breaking up the nice curves of the spring.', '2012-05-07 17:29:24.000000', NULL, 1),
(6762281, 1013233, 66384, '<td valign="top">Light is a bit harsh, especially on the upper part of the mushroom. The focus could have been better too.</td>', 'Light is a bit harsh, especially on the upper part of the mushroom. The focus could have been better too.', '2012-05-07 17:33:14.000000', NULL, 1),
